// Package probe reads the manifest of a lens probe: the defects a fixture
// plants, the place each one sits in, and the lens that is supposed to find it.
//
// The manifest is the answer key of the measurement. It is written by hand and
// reviewed like code, because a probe whose key is generated by the thing being
// measured grades itself. This package only reads it and refuses it when
// something is missing: a defect without a place, a lens nobody has, or a
// severity outside the closed vocabulary would each make the score a guess.
package probe

import (
	"bytes"
	"encoding/json"
	"fmt"
	"strings"

	"github.com/biggs-100/odachi/internal/domain/review"
)

// DefaultWindow is how many lines around a defect's line still count as that
// defect. It matches the review floor's own context: three lines hold a
// signature and its caller, and stop the rest of the file from being "here".
const DefaultWindow = 3

// Defect is one planted defect: where it is, which lens owes it, and how severe
// it is at least.
type Defect struct {
	// ID names the defect in the report. It is not shown to the reviewer.
	ID string `json:"id"`
	// Path is relative to the seeded arm of the fixture.
	Path string `json:"path"`
	// Line is the line in that path's seeded version.
	Line int `json:"line"`
	// Lens is the specialist that is supposed to find it.
	Lens string `json:"lens"`
	// Severity is the floor: a finding below it does not count as found.
	Severity review.Severity `json:"severity"`
	// Why is what the defect is, in one sentence, for the person reading the
	// report. An answer key nobody can check is not an answer key.
	Why string `json:"why"`
}

// Manifest is the fixture's answer key.
type Manifest struct {
	// Name is the fixture's name, for the report. Empty is allowed: it is named
	// by the folder when the command knows it.
	Name string `json:"name"`
	// Window is how many lines around Line still count, or zero for the default.
	Window int `json:"window"`
	// Defects is every planted defect. An empty list is refused: it measures
	// nothing and would report a perfect score for silence.
	Defects []Defect `json:"defects"`
}

// lenses is the closed vocabulary a defect's lens may name: the four the review
// carries, in their canonical order.
var lenses = []string{review.Risk, review.Readability, review.Reliability, review.Resilience}

// Parse reads a manifest and refuses it when it cannot be scored. Every message
// names the defect and the field, because the person who wrote it is the person
// who fixes it.
func Parse(data []byte) (Manifest, error) {
	var manifest Manifest
	decoder := json.NewDecoder(bytes.NewReader(data))
	// A typo'd key silently ignored is a defect nobody is measuring: the key is
	// the contract between the fixture and the report.
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(&manifest); err != nil {
		return Manifest{}, fmt.Errorf("the manifest is not readable: %w", err)
	}

	if manifest.Window == 0 {
		manifest.Window = DefaultWindow
	}
	if err := manifest.Validate(); err != nil {
		return Manifest{}, err
	}
	return manifest, nil
}

// Validate reports why the manifest cannot be scored, or nil.
func (m Manifest) Validate() error {
	if m.Window < 0 {
		return fmt.Errorf("the manifest window is %d: a window is zero or more lines around the defect", m.Window)
	}
	if len(m.Defects) == 0 {
		return fmt.Errorf("the manifest names no defect: a probe without defects measures nothing")
	}

	seen := make(map[string]bool, len(m.Defects))
	for _, defect := range m.Defects {
		if strings.TrimSpace(defect.ID) == "" {
			return fmt.Errorf("a defect at %s:%d has no id: the report names defects and cannot name this one", defect.Path, defect.Line)
		}
		if seen[defect.ID] {
			return fmt.Errorf("defect %q repeats an id that is already in the manifest", defect.ID)
		}
		seen[defect.ID] = true
		if strings.TrimSpace(defect.Path) == "" {
			return fmt.Errorf("defect %q names no path: a defect is a place in the seeded arm", defect.ID)
		}
		if defect.Line <= 0 {
			return fmt.Errorf("defect %q has line %d: a defect is one place, not the whole file", defect.ID, defect.Line)
		}
		if !knownLens(defect.Lens) {
			return fmt.Errorf("defect %q names the %q lens, and the lenses are %s", defect.ID, defect.Lens, strings.Join(lenses, ", "))
		}
		if !defect.Severity.Valid() {
			return fmt.Errorf("defect %q has severity %q: the vocabulary is BLOCKER, CRITICAL, WARNING, SUGGESTION", defect.ID, defect.Severity)
		}
		if strings.TrimSpace(defect.Why) == "" {
			return fmt.Errorf("defect %q does not say what it is: a key nobody can check is not a key", defect.ID)
		}
	}
	return nil
}

// knownLens reports whether the name is one of the four the review carries.
func knownLens(name string) bool {
	for _, lens := range lenses {
		if lens == name {
			return true
		}
	}
	return false
}
